import csv
import io


def rows_to_csv(rows, columns):
    """Serialise rows as CSV text, with a header line built from columns."""
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(columns)
    for row in rows:
        writer.writerow([row[c] for c in columns])
    return buf.getvalue()
